// Block (composition) — a bottom navigation bar docked to the bottom edge: full width, on the page's
// fill with an edge above, 3–5 icon+label items in equal columns. The docked take of BottomNav
// (block-contract.md §2: a later take is a sibling, the base is never renamed), for a product whose
// tab bar reads as part of the page rather than floating over it. DockedBar supplies the surface, the
// fixed position and the safe area; NavItem (orientation="vertical") each item and its current
// highlight; Grid the columns. The Block owns no look and mints no tokens. Posture: page chrome.
import type { ReactNode, Ref } from "react";
import { DockedBar } from "../components/DockedBar";
import { NavItem } from "../components/NavItem";
import { Grid } from "../layouts/Grid";
import "./BottomNavDocked.css";

export interface BottomNavDockedItemBase {
  /** Visible label under the icon. */
  label: string;
  /** Item icon (sized to the icon slot; inherits the item's text color). */
  icon: ReactNode;
  /** Marks the active tab — applies aria-current + the selected highlight. */
  isCurrent?: boolean;
}

/** Link or button, never both, mirroring NavItem's own mode union. */
export type BottomNavDockedItem = BottomNavDockedItemBase &
  (
    | {
        /** Destination. Present → renders a link. */
        href: string;
        onPress?: never;
      }
    | {
        href?: never;
        /** Press handler — button mode (no `href`). */
        onPress?: () => void;
      }
  );

export interface BottomNavDockedProps {
  /**
   * How the current destination is marked, forwarded to each NavItem: `item` fills its tile, `ink`
   * paints no fill and marks it by ink and weight alone.
   *
   * @default "item"
   */
  indicator?: "item" | "ink";
  /** Navigation destinations — intended for 3–5 top-level sections. */
  items: BottomNavDockedItem[];
  /** Accessible name for the navigation landmark. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function BottomNavDocked({
  indicator = "item",
  items,
  "aria-label": ariaLabel = "Primary",
  className,
  ref,
}: BottomNavDockedProps) {
  return (
    <DockedBar padding="none">
      <nav
        ref={ref}
        aria-label={ariaLabel}
        className={className ? `sd-bottomnav-docked ${className}` : "sd-bottomnav-docked"}
      >
        <Grid columns={items.length} gap="small" className="sd-bottomnav-docked__items">
          {items.map((item, index) =>
            item.href != null ? (
              <NavItem
                key={`${item.label}-${index}`}
                orientation="vertical"
                indicator={indicator}
                icon={item.icon}
                isCurrent={item.isCurrent}
                href={item.href}
              >
                {item.label}
              </NavItem>
            ) : (
              <NavItem
                key={`${item.label}-${index}`}
                orientation="vertical"
                indicator={indicator}
                icon={item.icon}
                isCurrent={item.isCurrent}
                onPress={item.onPress}
              >
                {item.label}
              </NavItem>
            ),
          )}
        </Grid>
      </nav>
    </DockedBar>
  );
}

/* BottomNavDocked.css — .sd-bottomnav-docked (Block)
   Arrangement only: the inset between the bar's edge and its items. DockedBar owns the surface, the
   edge, the fixed position and the safe area, and is set `padding="none"` so this inset is the only
   one; NavItem each item's look. */
.sd-bottomnav-docked {
  padding-block: var(--sd-space-x-small);
}

/* A NavItem is 4:3, narrower than a column on a wide bar: it sits in the middle of its column. */
.sd-bottomnav-docked__items {
  justify-items: center;
}
